function render(){ctx.clearRect(0,0,W,H);ctx.save();if(screenShake>0&&state==='playing')ctx.translate(rand(-screenShake*24,screenShake*24),rand(-screenShake*15,screenShake*15));drawBackground();if(state==='playing'||state==='gameover'){for(const e of enemies)drawEnemy(e);if(player)drawHero(player.x,player.y,player.face,heroScale(),heroes[heroIndex],player.walk,player.attack,player.jump,player.flash,player.skillAnim);for(const q of particles){ctx.globalAlpha=clamp(q.life/q.max,0,1);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x,q.y,q.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;for(const f of floaters){ctx.globalAlpha=clamp(f.life/f.max,0,1);txt(f.text,f.x,f.y,f.size,f.color,'center','system-ui','bold')}ctx.globalAlpha=1;if(state==='playing')drawHud();else drawGameOver()}else{drawHero(W*.21,floorY(),1,heroScale()*1.08,heroes[0],Math.sin(time)*.2);drawHero(W*.79,floorY(),-1,heroScale()*1.08,heroes[1],Math.sin(time+1)*.2);drawTitle()}ctx.restore()}
function menuAction(x,y){const m=menuLayout();if(x>W-62&&y<66){muted=!muted;sound(350,.07);return}if(y>=m.cardY-10&&y<=m.cardY+m.cardH+10){if(x>=m.cardX1-4&&x<=m.cardX1+m.cardW+4){heroIndex=0;sound(260,.07);return}if(x>=m.cardX2-4&&x<=m.cardX2+m.cardW+4){heroIndex=1;sound(340,.07);return}}if(y>=m.playY-16&&y<=m.playY+66){sound(390,.14);resetGame()}}
function touchPositions(){const small=W<540,pad=small?14:28,r=small?27:34,cy=H-(small?54:66);return{left:[pad+r,cy,r],right:[pad+r*2.9,cy,r],jump:[W-pad-r*5.4,cy,r],skill:[W-pad-r*2.95,cy,r],attack:[W-pad-r,cy,r]}}
const activePointers=new Map();
function gamePointerDown(x,y,id){if(state==='title'){menuAction(x,y);return}if(state==='gameover'){if(y>H*.8&&x<W*.3){state='title'}else resetGame();return}if(W>=900)return;for(const [action,[cx,cy,r]] of Object.entries(touchPositions())){if(Math.hypot(x-cx,y-cy)<=r+8){activePointers.set(id,action);if(action==='left')keys.ArrowLeft=true;if(action==='right')keys.ArrowRight=true;if(action==='attack')startAttack();if(action==='skill')useSkill();if(action==='jump'&&player.jump===0){player.jumpV=-440*heroScale();player.jump=1;sound(310,.08,'sine',.02)}return}}// tap playfield to turn toward / strike
 if(y<floorY()-35){if(x<player.x)player.face=-1;else player.face=1;startAttack()}}
function releasePointer(id){const action=activePointers.get(id);if(action==='left')keys.ArrowLeft=false;if(action==='right')keys.ArrowRight=false;activePointers.delete(id)}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture?.(e.pointerId);gamePointerDown(e.clientX,e.clientY,e.pointerId)});
canvas.addEventListener('pointerup',e=>{e.preventDefault();releasePointer(e.pointerId)});canvas.addEventListener('pointercancel',e=>releasePointer(e.pointerId));
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(state==='title'){if(e.code==='ArrowLeft'||e.code==='Digit1')heroIndex=0;if(e.code==='ArrowRight'||e.code==='Digit2')heroIndex=1;if(e.code==='Enter'||e.code==='Space')resetGame();if(e.code==='KeyM')muted=!muted} else if(state==='gameover'){if(e.code==='Escape')state='title';else if(e.code==='Enter'||e.code==='Space')resetGame()}else if(e.code==='Escape')state='title'});
addEventListener('keyup',e=>{keys[e.code]=false});addEventListener('blur',()=>{for(const id of activePointers.keys())releasePointer(id);for(const k in keys)keys[k]=false});
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();

