 function render(){ctx.clearRect(0,0,W,H);ctx.save();if(screenShake>0&&state==='playing')ctx.translate(rand(-screenShake*24,screenShake*24),rand(-screenShake*15,screenShake*15));drawBackground();if(state==='playing'||state==='gameover'){for(const e of enemies)drawEnemy(e);if(player)drawHero(player.x,player.y,player.face,heroScale(),heroes[heroIndex],player.walk,player.attack,player.jump,player.flash,player.skillAnim);for(const q of particles){ctx.globalAlpha=clamp(q.life/q.max,0,1);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x,q.y,q.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;for(const f of floaters){ctx.globalAlpha=clamp(f.life/f.max,0,1);txt(f.text,f.x,f.y,f.size,f.color,'center','system-ui','bold')}ctx.globalAlpha=1;if(state==='playing')drawHud();else drawGameOver()}else{drawHero(W*.21,floorY(),1,heroScale()*1.08,heroes[0],Math.sin(time)*.2);drawHero(W*.79,floorY(),-1,heroScale()*1.08,heroes[1],Math.sin(time+1)*.2);drawTitle()}ctx.restore()}
