+ if(y<floorY()-35){if(x<player.x)player.face=-1;else player.face=1;startAttack()}}
+function releasePointer(id){const action=activePointers.get(id);if(action==='left')keys.ArrowLeft=false;if(action==='right')keys.ArrowRight=false;activePointers.delete(id)}
