+addEventListener('keyup',e=>{keys[e.code]=false});addEventListener('blur',()=>{for(const id of activePointers.keys())releasePointer(id);for(const k in keys)keys[k]=false});
+function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
